746	    /**
747	     * A pair of one own generic and one declaration without static
748	     * parameters that the parameter-by-parameter check refuses, read on the
749	     * two declared domains: valid when one lies strictly inside the other and
750	     * the inner one's return type is below the outer one's for every
751	     * instance of the generic, its type parameters standing for themselves;
752	     * or when neither lies inside the other and declarations below both
753	     * cover their overlap (genericOverlapCovered).  Pairs of two generics
754	     * keep that check.
755	     */
756	    static private boolean validOnDeclaredDomains(Overload o1, Overload o2, Collection<Overload> all) {
757	        SingleFcn f1 = o1.getFn();
758	        SingleFcn f2 = o2.getFn();
759	        Overload gen;
760	        Overload plain;
761	        if (ownGeneric(f1) && !(f2 instanceof GenericFunctionOrMethod)) {
762	            gen = o1;
763	            plain = o2;
764	        } else if (ownGeneric(f2) && !(f1 instanceof GenericFunctionOrMethod)) {
765	            gen = o2;
766	            plain = o1;
767	        } else {
768	            return false;
769	        }
770	        if (hasRest(gen.getParams()) || hasRest(plain.getParams())) return false;
771	        if (gen.getParams().size() != plain.getParams().size()) return false;
772	        try {
773	            SingleFcn g = gen.getFn();
774	            SingleFcn p = plain.getFn();
775	            boolean plainInside = instanceHolding(g, plain.getParams(), true) != null;
776	            boolean genInside = declaredBelow(g, null, p, p, true);
777	            if (plainInside && genInside) return false;
778	            if (plainInside) return p.getRange().subtypeOf(g.getRange());
779	            if (genInside) return g.getRange().subtypeOf(p.getRange());
780	            return genericOverlapCovered(gen, plain, all);
781	        }
782	        catch (FortressException ex) {
783	            return false;
784	        }
785	    }

